<template><view class="login-page"><PreviewBadge/><view class="login-content"><image class="illustration" src="/static/images/login-travel.png" mode="aspectFit" aria-hidden="true"/><view class="actions"><button class="primary" @tap="authorize">手机号快捷登录</button><view class="consent-row"><checkbox-group @change="consent=$event.detail.value.includes('yes')"><label class="checkbox-label"><checkbox value="yes" :checked="consent" color="#164E70"/><text class="sr-text">同意协议</text></label></checkbox-group><view class="consent-copy"><view>我已阅读并同意</view><view class="consent-links"><button class="agreement-link" @tap="terms('用户服务协议')">《用户服务协议》</button>和<button class="agreement-link" @tap="terms('隐私保护指引')">《隐私保护指引》</button></view></view></view><text v-if="error" class="error">{{error}}</text><button class="text-button skip" @tap="cancel">暂不登录，继续浏览</button></view></view></view></template>
<script setup lang="ts">
import {ref} from 'vue';import {useMallPreviewStore} from '@/store/mall-preview';import {returnFromLogin} from '@/utils/auth-routing';import PreviewBadge from './PreviewBadge.vue';
const mall=useMallPreviewStore();const consent=ref(false),error=ref('');
function terms(title:string){uni.showModal({title:`${title}（演示）`,content:'本模式不读取正式协议、不发起微信授权。勾选仅用于检查页面交互，不构成真实注册或协议签署。',showCancel:false});}
function authorize(){if(!consent.value){error.value='请先阅读并勾选同意协议';return;}uni.showActionSheet({itemList:['模拟授权成功','模拟拒绝授权','模拟取消授权','模拟授权失败'],success:({tapIndex})=>{if(tapIndex===0){mall.login();const target=mall.pendingTarget||'/pages/account/index';mall.pendingTarget='';mall.pendingOrigin='';returnFromLogin(target);}else error.value=['','您未同意授权，可继续浏览或主动重试','授权已取消，可继续浏览','授权未完成，请主动重试'][tapIndex];}});}
function cancel(){const target=mall.pendingOrigin||'/pages/mall/index';mall.pendingOrigin='';mall.pendingTarget='';returnFromLogin(target);}
</script><style lang="scss" scoped>@import '@/mall/login.scss';</style>
